        for(let i=0;i<pixels.length;i+=4){const r=pixels[i],g=pixels[i+1],b=pixels[i+2],max=Math.max(r,g,b),min=Math.min(r,g,b);const gray=max-min<20&&r>88&&r<238;const red=r>180&&g<90&&b<90;const color=max-min>28&&max>105&&!red;if(gray||color)fill++;}
